const API_URL = 'https://sudoku-api-chi.vercel.app/api';

// --- API (ÇEVRİMİÇİ) FONKSİYONLARI ---

export const generateSudokuFromApi = async (size, difficulty) => {
    try {
        const response = await fetch(`${API_URL}/generate`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ size, difficulty })
        });
        if (!response.ok) throw new Error('API yanıt vermedi');
        return await response.json();
    } catch (error) {
        console.error('API Sudoku üretim hatası:', error);
        return null;
    }
};

export const solveSudokuFromApi = async (size, grid) => {
    try {
        const response = await fetch(`${API_URL}/solve`, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ size, grid, max_solutions: 100 })
        });
        if (!response.ok) throw new Error('API yanıt vermedi');
        return await response.json();
    } catch (error) {
        console.error('API Sudoku çözüm hatası:', error);
        return null;
    }
};


// --- YEREL (ÇEVRİMDIŞI WORKER VE ARAYÜZ) FONKSİYONLARI ---

export const createEmptyGrid = (size = 9) => Array(size).fill(null).map(() => Array(size).fill(0));

export const isValid = (grid, row, col, num, size = 9) => {
    const boxSize = size === 4 ? 2 : 3;
    
    // Satır ve sütun kontrolü
    for (let x = 0; x < size; x++) {
        if (grid[row][x] === num) return false;
        if (grid[x][col] === num) return false;
    }
    
    // Kutu kontrolü
    const startRow = row - (row % boxSize);
    const startCol = col - (col % boxSize);
    for (let i = 0; i < boxSize; i++) {
        for (let j = 0; j < boxSize; j++) {
            if (grid[i + startRow][j + startCol] === num) return false;
        }
    }
    return true;
};

export const shuffle = (array) => {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
    return array;
};

export const findAllSolutions = (grid, limit = 2000, size = 9) => {
    const solutions = [];
    const find = (currentGrid) => {
        if (solutions.length >= limit) return;

        for (let row = 0; row < size; row++) {
            for (let col = 0; col < size; col++) {
                if (currentGrid[row][col] === 0) {
                    for (let num = 1; num <= size; num++) {
                        if (isValid(currentGrid, row, col, num, size)) {
                            currentGrid[row][col] = num;
                            find(currentGrid);
                            currentGrid[row][col] = 0; 
                        }
                    }
                    return;
                }
            }
        }
        solutions.push(JSON.parse(JSON.stringify(currentGrid)));
    };
    
    find(JSON.parse(JSON.stringify(grid)));
    return shuffle(solutions);
};

export const fillGrid = (grid, size = 9) => {
    const totalCells = size * size;
    for (let i = 0; i < totalCells; i++) {
        const row = Math.floor(i / size);
        const col = i % size;
        
        if (grid[row][col] === 0) {
            const numbers = shuffle(Array.from({ length: size }, (_, i) => i + 1));
            for (const num of numbers) {
                if (isValid(grid, row, col, num, size)) {
                    grid[row][col] = num;
                    if (fillGrid(grid, size)) return true;
                    grid[row][col] = 0;
                }
            }
            return false;
        }
    }
    return true;
};

export const generateSudoku = (removals, size = 9) => {
    let bestPuzzle = null;
    let bestRemovedCount = -1;
    let attempts = 0;
    const maxAttempts = 30;
    const totalCells = size * size;

    while (attempts < maxAttempts) {
        const grid = createEmptyGrid(size);
        fillGrid(grid, size);

        const solution = JSON.parse(JSON.stringify(grid));
        let puzzle = JSON.parse(JSON.stringify(solution));

        const cells = shuffle(Array.from({ length: totalCells }, (_, i) => i));
        let removedCount = 0;

        for (const cellIndex of cells) {
            if (removedCount >= removals) break;

            const row = Math.floor(cellIndex / size);
            const col = cellIndex % size;

            if (puzzle[row][col] === 0) continue;

            const temp = puzzle[row][col];
            puzzle[row][col] = 0;

            const solutions = findAllSolutions(puzzle, 2, size);
            if (solutions.length !== 1) {
                puzzle[row][col] = temp;
            } else {
                removedCount++;
            }
        }

        if (removedCount >= removals) {
            return { puzzle, solution };
        }

        if (removedCount > bestRemovedCount) {
            bestRemovedCount = removedCount;
            bestPuzzle = { puzzle, solution };
        }
        
        attempts++;
    }

    if (bestRemovedCount < removals) {
        console.warn(`Maximum attempts reached. Target: ${removals}, Best: ${bestRemovedCount}`);
    }

    return bestPuzzle;
};

export const validateGrid = (grid) => {
    const invalidCells = new Set();
    const size = grid.length;
    const boxSize = size === 4 ? 2 : 3;

    const addInvalid = (r, c) => invalidCells.add(`${r}-${c}`);

    for (let i = 0; i < size; i++) {
        const rowMap = new Map();
        const colMap = new Map();
        for (let j = 0; j < size; j++) {
            
            const rowCell = grid[i][j];
            if (rowCell !== 0) {
                if (rowMap.has(rowCell)) {
                    addInvalid(i, j);
                    addInvalid(i, rowMap.get(rowCell));
                }
                rowMap.set(rowCell, j);
            }
            
            const colCell = grid[j][i];
            if (colCell !== 0) {
                if (colMap.has(colCell)) {
                    addInvalid(j, i);
                    addInvalid(colMap.get(colCell), i);
                }
                colMap.set(colCell, j);
            }
        }
    }

    for (let boxRow = 0; boxRow < size; boxRow += boxSize) {
        for (let boxCol = 0; boxCol < size; boxCol += boxSize) {
            const boxMap = new Map();
            for (let i = 0; i < boxSize; i++) {
                for (let j = 0; j < boxSize; j++) {
                    const r = boxRow + i;
                    const c = boxCol + j;
                    const cellValue = grid[r][c];
                    
                    if (cellValue !== 0) {
                        if (boxMap.has(cellValue)) {
                            const [prev_r, prev_c] = boxMap.get(cellValue);
                            addInvalid(r, c);
                            addInvalid(prev_r, prev_c);
                        }
                        boxMap.set(cellValue, [r, c]);
                    }
                }
            }
        }
    }

    return Array.from(invalidCells).map(coord => {
        const [row, col] = coord.split('-').map(Number);
        return { row, col };
    });
};